mapper.select:
SELECT d.dong_code AS dongCode, COALESCE(m.bus_stop_count, 0) AS busStopCount FROM dongcodes d LEFT JOIN dong_bus_stop_metrics m ON m.dong_code = d.dong_code WHERE d.dong_code IN
#{dongCode}
ORDER BY d.dong_code

SELECT d.dong_code AS dongCode, COUNT(DISTINCT s.station_name) AS stationCount, COUNT(DISTINCT s.line_name) AS lineCount, COUNT(DISTINCT s.station_name) * 2 + GREATEST(COUNT(DISTINCT s.line_name) - COUNT(DISTINCT s.station_name), 0) AS subwayIndex FROM dongcodes d LEFT JOIN subway_stations s ON s.dong_code = d.dong_code WHERE d.dong_code IN
#{dongCode}
GROUP BY d.dong_code ORDER BY d.dong_code
